            }, { signal: controller.signal })
            window.addEventListener('pointerup', () => {
                controller.abort()
                if (sizeStorageKey && paperRef.current) {
                    const paperBounds = paperRef.current.getBoundingClientRect()
                    applicationStorage.setItem(sizeStorageKey, JSON.stringify({ height: paperBounds.height, width: paperBounds.width }))
                }
            }, { signal: controller.signal })
        } catch (error) {
            resizeRef.current?.abort()
            dialogService.error(error, { fallbackMessage: 'Popover resize could not be started' })
        }
    }

    return (
        <Popover
            anchorEl={anchorElement}
            anchorOrigin={anchorOrigin}
            marginThreshold={POPOVER_TOP_MARGIN}
            onClose={handleClose}
            open={open}
            slotProps={{
